private theorem power_log_payment {X t delta A : ℝ} {E : ℕ}
    (hX : 0 < X) (ht : 0 < t) (hpay : t ^ (A + (E : ℝ)) ≤ X ^ delta) :
    t ^ E * X ^ (-delta) ≤ 1 / t ^ A

private theorem exists_log_power_threshold (P : ℝ) {delta : ℝ} (hdelta : 0 < delta) :
    ∃ x0 : ℝ, 1 < x0 ∧ ∀ X : ℝ, x0 ≤ X →
      1 ≤ Real.log X ∧ (Real.log X) ^ P ≤ X ^ delta

